using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;
using ScanRelay.Core.Modules;

namespace ScanRelay.Installer;

/// <summary>
/// Everything setup asks. The wizard fills one in page by page; silent mode reads one
/// from a file. It holds no secrets: the printer account's password is generated by
/// setup and only ever stored, protected, in <c>install.json</c>.
/// </summary>
public sealed partial class SetupAnswers
{
    public const string FirewallRuleName = "ScanRelay admin screen";

    /// <summary>Where the program files go.</summary>
    public string InstallFolder { get; set; } = WinPath.Combine(SpecialFolder(Environment.SpecialFolder.ProgramFiles, @"C:\Program Files"), "ScanRelay");

    /// <summary>Where scans, the database and logs are kept. Hidden, and closed to everyone but the service and administrators.</summary>
    public string DataFolder { get; set; } = WinPath.Combine(SpecialFolder(Environment.SpecialFolder.CommonApplicationData, @"C:\ProgramData"), "ScanRelay");

    /// <summary>The name admins type to reach the admin screen, and printers use to reach the share.</summary>
    public string HostName { get; set; } = DefaultHostName();

    public int Port { get; set; } = 8443;

    /// <summary>An existing certificate in the machine store, or null for setup to make a self-signed one.</summary>
    public string? WebCertThumbprint { get; set; }

    /// <summary>The local account printers sign in with to write to the share.</summary>
    public string PrinterAccount { get; set; } = "scanrelay-printer";

    public string ShareName { get; set; } = "Scans$";

    /// <summary>Official modules to have installed, by id, fetched from the GitHub catalog.</summary>
    public List<string> Modules { get; set; } = [];

    /// <summary>Module files that are not from the project. Only installed with <see cref="AcceptCustomModules"/>.</summary>
    public List<string> CustomModuleFiles { get; set; } = [];

    /// <summary>The admin has read the warning about custom modules and agreed.</summary>
    public bool AcceptCustomModules { get; set; }

    /// <summary>Official module files, each with its <c>.sig</c> beside it, for a server with no internet.</summary>
    public List<string> OfflineModuleFiles { get; set; } = [];

    /// <summary>Installed modules to take out.</summary>
    public List<string> RemoveModules { get; set; } = [];

    public bool UpdateCheck { get; set; } = true;

    public bool AddFirewallRule { get; set; } = true;

    /// <summary>The repo that publishes releases and the module catalog.</summary>
    public string Repository { get; set; } = "echoots1/ScanRelay";

    /// <summary>Repair: reopen the local-only setup screen, for when sign-in is broken.</summary>
    public bool ReopenSetup { get; set; }

    /// <summary>Repair: replace the certificate the service uses to sign in to Microsoft 365.</summary>
    public bool RenewGraphCertificate { get; set; }

    [JsonIgnore]
    public string Url => $"https://{HostName}:{Port}";

    /// <summary>The address setup itself uses to open and check the admin screen.</summary>
    [JsonIgnore]
    public string LocalUrl => $"https://localhost:{Port}";

    [JsonIgnore]
    public string InboxFolder => WinPath.Combine(DataFolder, "Inbox");

    [JsonIgnore]
    public string ModulesFolder => WinPath.Combine(InstallFolder, "Modules");

    /// <summary>Strict, so a mistyped name in an answers file is an error, not a silently ignored line.</summary>
    private static readonly JsonSerializerOptions FileJson = new()
    {
        WriteIndented = true,
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true,
        UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow,
    };

    public string ToJson() => JsonSerializer.Serialize(this, FileJson);

    public static SetupAnswers FromJson(string json)
    {
        try
        {
            return JsonSerializer.Deserialize<SetupAnswers>(json, FileJson) ?? throw new SetupException("The answers file is empty.");
        }
        catch (JsonException e)
        {
            throw new SetupException("The answers file could not be read: " + e.Message);
        }
    }

    public SetupAnswers Clone() => FromJson(ToJson());

    /// <summary>What is kept for the next Modify or Repair: the lasting choices, not the one-off requests.</summary>
    public SetupAnswers ForSaving(IEnumerable<string> installedOfficialModules)
    {
        var saved = Clone();
        saved.Modules = [.. installedOfficialModules.Order(StringComparer.Ordinal)];
        saved.CustomModuleFiles = [];
        saved.OfflineModuleFiles = [];
        saved.RemoveModules = [];
        saved.AcceptCustomModules = false;
        saved.ReopenSetup = false;
        saved.RenewGraphCertificate = false;
        return saved;
    }

    [GeneratedRegex(@"^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*$")]
    private static partial Regex HostPattern();

    [GeneratedRegex("^[a-z0-9]+(-[a-z0-9]+)*$")]
    private static partial Regex ModuleIdPattern();

    [GeneratedRegex(@"^[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9._-]+$")]
    private static partial Regex RepositoryPattern();

    /// <summary>Everything wrong with the answers, in words an admin can act on. Empty when they are fine.</summary>
    public IReadOnlyList<string> Validate()
    {
        var p = new List<string>();

        var installOk = CheckFolder(p, "The install folder", InstallFolder);
        var dataOk = CheckFolder(p, "The data folder", DataFolder);
        if (installOk && dataOk)
        {
            if (WinPath.IsSameOrInside(DataFolder, InstallFolder)) p.Add("The data folder cannot be inside the install folder. The service must not be able to write to its own program files.");
            else if (WinPath.IsSameOrInside(InstallFolder, DataFolder)) p.Add("The install folder cannot be inside the data folder.");
        }

        if (string.IsNullOrWhiteSpace(HostName) || HostName.Length > 253 || !HostPattern().IsMatch(HostName))
        {
            p.Add("The host name must be a DNS name or address such as scans.example.com, without https:// or a port.");
        }

        if (Port is < 1 or > 65535) p.Add("The port must be a number from 1 to 65535.");

        if (WebCertThumbprint is not null && NormaliseThumbprint(WebCertThumbprint).Length != 40)
        {
            p.Add("The web certificate thumbprint must be 40 letters and digits (0-9, A-F), or left out for a self-signed certificate.");
        }

        CheckAccount(p);
        CheckShare(p);

        foreach (var id in Modules.Concat(RemoveModules).Distinct().Where(id => !ModuleIdPattern().IsMatch(id ?? "")))
        {
            p.Add($"\"{id}\" is not a module id. Ids are lower-case letters, digits and hyphens.");
        }

        foreach (var id in Modules.Intersect(RemoveModules))
        {
            p.Add($"The module \"{id}\" is listed both to install and to remove.");
        }

        foreach (var file in CustomModuleFiles.Concat(OfflineModuleFiles))
        {
            if (string.IsNullOrWhiteSpace(file) || !file.EndsWith(ModulePackage.Extension, StringComparison.OrdinalIgnoreCase))
            {
                p.Add($"\"{file}\" is not a module file. Module files end in {ModulePackage.Extension}.");
            }
        }

        if (CustomModuleFiles.Count > 0 && !AcceptCustomModules)
        {
            p.Add("Custom modules are not from the project and have not been checked by it. They are only installed when that has been accepted (AcceptCustomModules).");
        }

        if (!RepositoryPattern().IsMatch(Repository ?? "")) p.Add("The repository must look like owner/name.");
        return p;
    }

    /// <summary>A thumbprint as the certificate store compares it: hex digits only, upper case.</summary>
    public static string NormaliseThumbprint(string thumbprint) =>
        new string([.. thumbprint.Where(char.IsAsciiHexDigit)]).ToUpperInvariant();

    private static bool CheckFolder(List<string> p, string what, string? path)
    {
        if (string.IsNullOrWhiteSpace(path) || !WinPath.IsRooted(path))
        {
            p.Add($"{what} must be a full path on a local drive, such as C:\\Folder.");
            return false;
        }

        var rest = path[3..];
        if (rest.Trim('\\', ' ').Length == 0)
        {
            p.Add($"{what} cannot be the top of a drive.");
            return false;
        }

        if (rest.IndexOfAny(['<', '>', '"', '|', '?', '*', ':', '/']) >= 0 || rest.Any(char.IsControl)
            || rest.Split('\\').Any(part => part is "." or ".." || part.EndsWith(' ') || part.EndsWith('.')))
        {
            p.Add($"{what} has characters that Windows does not allow in a folder path.");
            return false;
        }

        if (path.Length > 200)
        {
            p.Add($"{what} is too long. Keep it under 200 characters.");
            return false;
        }

        return true;
    }

    private void CheckAccount(List<string> p)
    {
        const string notAllowed = "\"/\\[]:;|=,+*?<>";
        var name = PrinterAccount ?? "";
        if (name.Length is 0 or > 20) p.Add("The printer account name must be 1 to 20 characters.");
        else if (name.IndexOfAny(notAllowed.ToCharArray()) >= 0 || name.Any(char.IsControl)) p.Add("The printer account name cannot contain any of " + notAllowed);
        else if (name.Trim('.', ' ').Length == 0 || name.EndsWith('.') || name != name.Trim()) p.Add("The printer account name cannot start or end with a space, or end with a full stop.");
    }

    private void CheckShare(List<string> p)
    {
        const string notAllowed = "\"/\\[]:|<>+=;,?*";
        var name = ShareName ?? "";
        if (name.Length < 2 || !name.EndsWith('$')) p.Add("The share name must end with $, which is what hides it from people browsing the server.");
        else if (name.Length > 80) p.Add("The share name must be 80 characters or fewer.");
        else if (name.IndexOfAny(notAllowed.ToCharArray()) >= 0 || name.Any(char.IsControl) || name != name.Trim()) p.Add("The share name cannot contain any of " + notAllowed);
        else if (name.Length == 2 || new[] { "ADMIN$", "IPC$", "PRINT$" }.Contains(name, StringComparer.OrdinalIgnoreCase)) p.Add($"{name} is a share name Windows keeps for itself. Choose another.");
    }

    private static string SpecialFolder(Environment.SpecialFolder folder, string fallback)
    {
        var path = Environment.GetFolderPath(folder);
        return WinPath.IsRooted(path) ? path : fallback;
    }

    private static string DefaultHostName()
    {
        try
        {
            var properties = System.Net.NetworkInformation.IPGlobalProperties.GetIPGlobalProperties();
            var name = string.IsNullOrEmpty(properties.DomainName) ? properties.HostName : $"{properties.HostName}.{properties.DomainName}";
            if (!string.IsNullOrWhiteSpace(name)) return name.ToLowerInvariant();
        }
        catch (Exception e) when (e is System.Net.NetworkInformation.NetworkInformationException or PlatformNotSupportedException)
        {
        }

        return Environment.MachineName.ToLowerInvariant();
    }
}

/// <summary>
/// Windows path rules as plain string work, so the checks and the summary give the
/// same answers in tests on any machine as they do on the server.
/// </summary>
public static class WinPath
{
    public static bool IsRooted(string? path) =>
        path is { Length: >= 3 } && char.IsAsciiLetter(path[0]) && path[1] == ':' && path[2] == '\\';

    public static string Normalise(string path)
    {
        var trimmed = path.Trim().Replace('/', '\\').TrimEnd('\\');
        return trimmed.Length == 2 ? trimmed + "\\" : trimmed;
    }

    public static string Combine(string folder, string name) => Normalise(folder).TrimEnd('\\') + "\\" + name;

    public static bool Same(string a, string b) => Normalise(a).Equals(Normalise(b), StringComparison.OrdinalIgnoreCase);

    public static bool IsSameOrInside(string path, string folder)
    {
        var child = Normalise(path);
        var parent = Normalise(folder);
        return child.Equals(parent, StringComparison.OrdinalIgnoreCase)
            || child.StartsWith(parent.TrimEnd('\\') + "\\", StringComparison.OrdinalIgnoreCase);
    }
}

/// <summary>A failure with a message meant for the admin, not a stack trace.</summary>
public sealed class SetupException(string message, Exception? inner = null) : Exception(message, inner);
